/* ========================================================== */

/* ---------- loader: terminal intro (first visit per session) ---------- */
const loader = $('#loader');
const heroIn = () => {
  if (RM) return;
  $$('.h-in').forEach((el,i) => el.animate([{opacity:0, transform:'translateY(28px)'},{opacity:1, transform:'none'}], {duration:900, delay:80*i, easing:'cubic-bezier(.22,.8,.24,1)', fill:'backwards'}));
};
let seenIntro = false; try { seenIntro = sessionStorage.getItem('intro') === '1'; } catch(e){}
if (RM || seenIntro) { loader.classList.add('gone'); heroIn(); }
else {
  document.documentElement.style.overflow = 'hidden';
  let finished = false; const timers = [];
  const later = (fn, ms) => timers.push(setTimeout(fn, ms));
  const finish = () => {
    if (finished) return; finished = true; timers.forEach(clearTimeout);
    try { sessionStorage.setItem('intro','1'); } catch(e){}
    loader.classList.add('leaving');
    later(() => { loader.classList.add('done'); document.documentElement.style.overflow = ''; heroIn(); }, 350);
    setTimeout(() => loader.classList.add('gone'), 1500);
  };
  const q = 'who is pooja lingwat?'; let i = 0;
  const lines = $$('#tout p'), enter = $('#tenter');
  const type = () => {
    $('#tq').textContent = q.slice(0, ++i);
    if (i < q.length) later(type, 38 + Math.random() * 40);
    else {
      later(() => { $('#tcaret').style.display = 'none'; }, 250);
      lines.forEach((l, k) => later(() => l.classList.add('on'), 450 + k * 260));
      const after = 450 + lines.length * 260;
      later(() => enter.classList.add('on'), after + 200);
      later(finish, after + 2600);          // auto-continue so nobody gets stuck
    }
  };
  later(type, 700);
  enter.addEventListener('click', finish);
  $('#ldskip').addEventListener('click', finish);
  addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === 'Escape' || e.key === ' ') { e.preventDefault(); finish(); } });
}

/* ---------- nav ---------- */
const nav = $('#nav'), menu = $('#menu'), sheet = $('#sheet');
menu.addEventListener('click', () => { const o = sheet.classList.toggle('open'); menu.setAttribute('aria-expanded', String(o)); });

/* ---------- smooth scroll ---------- */
let lenis = null;
if (!RM && window.Lenis) { lenis = new Lenis({ duration:1.15, easing:t => 1 - Math.pow(1 - t, 3) }); const raf = t => { lenis.raf(t); requestAnimationFrame(raf); }; requestAnimationFrame(raf); }
$$('a[href^="#"]').forEach(a => a.addEventListener('click', e => {
  const id = a.getAttribute('href'); const t = id.length > 1 && document.querySelector(id); if (!t) return;
  e.preventDefault(); sheet.classList.remove('open'); menu.setAttribute('aria-expanded','false');
  lenis ? lenis.scrollTo(t, { offset:-76 }) : t.scrollIntoView({ behavior: RM ? 'auto' : 'smooth' });
}));

const secs = ['about','projects','experience','recognition','contact'].map(id => document.getElementById(id));
const onScroll = () => {
  nav.classList.toggle('solid', scrollY > 30);
  let cur = ''; secs.forEach(s => { if (s.getBoundingClientRect().top < innerHeight * .4) cur = s.id; });
  $$('.nav-links a').forEach(a => a.classList.toggle('on', a.getAttribute('href') === '#' + cur));
  const tl = $('#tl'), r = tl.getBoundingClientRect();
  tl.style.setProperty('--p', RM ? 1 : clamp((innerHeight * .65 - r.top) / r.height).toFixed(3));
  $$('#tl > li').forEach(li => li.classList.toggle('lit', li.getBoundingClientRect().top < innerHeight * .65));
};
addEventListener('scroll', onScroll, { passive:true }); onScroll();

/* ---------- tech rails ---------- */
const pill = ([n, hex, path]) => `<span class="tool" style="--c:${hex}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>${n}</span>`;
const half = Math.ceil(TOOLS.length / 2);
[[TOOLS.slice(0, half), '#rail1'], [TOOLS.slice(half), '#rail2']].forEach(([list, sel]) => {
  const html = list.map(pill).join(''); $(sel + ' .track').innerHTML = html + html;
});

/* ---------- project art (drawn previews until real screenshots) ---------- */
const dots = Array.from({length:22},(_,i)=>`<circle cx="${50+((i*53)%210)}" cy="${80+((i*97)%230)}" r="5" fill="#6E5E5C"/>`).join('');
const bars = [60,90,45,120,80,150,70].map((h,i)=>`<rect x="${330+i*38}" y="${300-h}" width="24" height="${h}" rx="4" fill="${h>140?'#B23A48':i%2?'#A9BCA2':'#7E9878'}"/>`).join('');
