/* ---------- reveals + count-up ---------- */
const countUp = el => {
  const to = +el.dataset.count; if (RM) { el.textContent = to; return; }
  const t0 = performance.now(); const step = n => { const k = clamp((n - t0) / 1200); el.textContent = Math.round(to * (1 - Math.pow(1 - k, 3))); if (k < 1) requestAnimationFrame(step); }; requestAnimationFrame(step);
};
const io = new IntersectionObserver(es => es.forEach(e => {
  if (!e.isIntersecting) return; e.target.classList.add('in'); io.unobserve(e.target);
  e.target.querySelectorAll('[data-count]').forEach(countUp);
}), { threshold:.12 });
$$('.reveal').forEach(el => io.observe(el));

/* ---------- certificates ---------- */
$('#certs').innerHTML = CERTS.map(c => `<li><div>${c.name}<span>${c.by}</span></div>${c.url ? `<a href="${c.url}" target="_blank" rel="noopener">View certificate &#8599;</a>` : '<em>link coming</em>'}</li>`).join('');

/* ---------- live GitHub ---------- */
const setGh = (id, v) => { $(id).textContent = v; };
fetch('https://api.github.com/users/poojawork102').then(r => r.ok ? r.json() : Promise.reject()).then(u => {
  setGh('#gh-repos', u.public_repos); setGh('#gh-followers', u.followers); setGh('#gh-since', new Date(u.created_at).getFullYear());
}).catch(() => { ['#gh-repos','#gh-followers','#gh-since'].forEach(id => setGh(id, '-')); });
const chartEl = $('#chart');
const chartFallback = () => {
  const img = new Image(); img.alt = 'GitHub contribution chart for poojawork102';
  img.onload = () => { chartEl.classList.add('img'); chartEl.innerHTML = ''; chartEl.appendChild(img); };
  img.onerror = () => { chartEl.innerHTML = '<span class="chart-msg">Contribution chart unavailable right now</span>'; };
  img.src = 'https://ghchart.rshah.org/7A1F33/poojawork102';
};
fetch('https://github-contributions-api.jogruber.de/v4/poojawork102?y=last').then(r => r.ok ? r.json() : Promise.reject()).then(d => {
  const days = d.contributions || []; if (!days.length) throw 0;
  const lv = ['#E4DCCB','#CBD6C3','#9DB497','#6F8B69','#7A1F33'];
  const start = new Date(days[0].date).getDay(), cell = 11, gap = 3;
  const weeks = Math.ceil((days.length + start) / 7);
  let rects = '';
  days.forEach((day, i) => { const k = i + start, x = Math.floor(k / 7) * (cell + gap), y = (k % 7) * (cell + gap);
    rects += `<rect x="${x}" y="${y}" width="${cell}" height="${cell}" rx="2.5" fill="${lv[day.level] || lv[0]}"><title>${day.count} on ${day.date}</title></rect>`; });
  const total = d.total ? Object.values(d.total).reduce((a, b) => a + b, 0) : days.reduce((a, b) => a + b.count, 0);
  chartEl.innerHTML = `<svg viewBox="0 0 ${weeks * (cell + gap)} ${7 * (cell + gap)}" role="img" aria-label="${total} contributions in the last year">${rects}</svg><div class="chart-foot"><span>${total} contributions in the last year</span><span class="legend">Less ${lv.map(c => `<i style="background:${c}"></i>`).join('')} More</span></div>`;
}).catch(chartFallback);

